package com.google.gson.stream;

import com.google.gson.internal.JsonReaderInternalAccess;
import com.google.gson.internal.bind.JsonTreeReader;
import com.google.gson.stream.JsonReader;
import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.Closeable;
import java.io.EOFException;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

public class JsonReader_nextInt_TriageGen2Test {

    private JsonReader jsonReader;

    @Before
    public void setUp() throws IOException {
        jsonReader = new JsonReader(new InputStreamReader(new ByteArrayInputStream("".getBytes())));
    }

    @After
    public void tearDown() throws IOException {
        jsonReader.close();
    }

    @Test
    public void testNextIntWithValidInteger() throws IOException {
        jsonReader = new JsonReader(new InputStreamReader(new ByteArrayInputStream("123".getBytes())));
        assertEquals(123, jsonReader.nextInt());
    }




















}

